//! Wire protocols spoken with processes outside the core.
//!
//! `teams_bridge.proto` is the single source of truth; `generated/` holds the Rust code
//! rust-protobuf 3.7.2 produces from it. The code is checked in (instead of generated by a build
//! script) so building the core needs no code generator; `generated_code_tests` fails when the
//! checked-in code no longer matches the schema. See `README.md` for the specification.

/// Generated Protobuf messages for the Teams bot bridge (`teams_bridge.proto`); do not edit.
#[allow(clippy::all, clippy::pedantic, missing_docs, unused_qualifications)]
pub mod generated;

#[cfg(test)]
mod generated_code_tests;

pub use generated::teams_bridge;
